/**
 * Ein Eintrag für den Google-Merchant-Feed — und die Entscheidung, ob ein Produkt hineingehört.
 *
 * WARUM EIGENES MODUL (gemessen 2026-10-17):
 * Der Generator `automation/autopilot/merchant_feed.mjs` schrieb bei JEDEM Produkt
 * `<g:identifier_exists>no</g:identifier_exists>` und liess `google_product_category` ganz weg —
 * obwohl der Shop beides hat: **84 % der Fortura-Artikel tragen einen Barcode (GTIN)** und
 * **100 % der zuletzt geänderten 600 Produkte haben ein `mm-google-shopping.google_product_category`**.
 * Ein Feed, der eine vorhandene GTIN verschweigt, verliert in Google Shopping die Zuordnung zum
 * Produkt (keine Preisvergleich-Karte, schlechtere Platzierung) — und `identifier_exists:no` bei
 * einem Artikel MIT GTIN ist schlicht eine Falschangabe gegenüber Google.
 *
 * Zweitens filterte der Generator nur über eine handgeschriebene Titel-Liste (`nike|adidas|…`).
 * Die Sperrtags, die der Katalog selbst trägt (`nicht-google-bewerben`, `gmc-adult-pull`,
 * `google-policy-flag`, …), las er NICHT — dieselbe Falle wie beim `publish_guard`:
 * TAGS LESEN, BEVOR MAN HANDELT. Hier zählt sie doppelt, weil ein Adult-Artikel im
 * Merchant-Feed eine Kontosperre kosten kann.
 */
import { sperrTags } from './kanal_sperren.mjs';

/**
 * Lizenz-/Figurennamen. Ein Kostüm „Batman Classic" oder „Kostüm Pokemon Pikachu" im
 * Merchant-Feed ist der klassische Grund für eine KONTOSPERRE (Markenrechtsverletzung) —
 * schlimmer als ein einzelner abgelehnter Artikel.
 *
 * GEMESSEN 2026-10-24 an der Fortura-Ware (2371 aktive Produkte): **31 Artikel mit einem
 * Lizenznamen gingen durch** — `RISIKO` kannte nur `disney|frozen`, und „Kostüm Batman Classic"
 * enthält weder „kinder" noch eine der Markenwörter. Alle 31 Titel wurden EINZELN nachgelesen,
 * bevor ein Name hier steht: Harry Potter, Batman, Superman, Sonic, Super Mario, Paw Patrol,
 * Pokemon, Hello Kitty, Spiderman, Mickey Mouse, Peppa, Barbie. Kein Fehltreffer darunter.
 *
 * Die Wortgrenzen sind nicht Zierde, sondern die Gegenprobe (vierte Wiederholung der Klasse
 * „zu breites Muster", vgl. `rueckhol` und `/ring\b/`): ohne `\b` trifft `sonic` das Wort
 * „ultrasonic" und `mario` die „Marionette" — beides harmlose Ware, die stumm verschwände.
 * BEWUSST NICHT IM MUSTER: `anna` und `elsa`. Die Gegenprobe fing sie — `anna` trifft über die
 * Wortgrenze am Bindestrich den Vornamen in „Kapuzenpullover «Anna-Lena»". Beide sind gewöhnliche
 * Vornamen; die Frozen-Figuren deckt `frozen` in `RISIKO` ab. Nicht nachtragen.
 */
export const LIZENZ = /\b(harry potter|batman|superman|spider[- ]?man|paw patrol|pok[eé]mon|peppa|star wars|marvel|avengers|minions?|hello kitty|barbie|mickey|minnie|super mario|sonic|bluey|spongebob|hulk|iron man|captain america)\b/i;

/** Titel/Marken, die Google als Markenfälschungs- oder Safety-Risiko lesen kann. */
export const RISIKO = /\b(nike|adidas|puma|reebok|converse|vans|disney|frozen|timberland|chanel|gucci|rolex|louis vuitton|supreme)\b|baby|kinder|lern-tablet|schwimmring|schwimmbrille|schwimmflügel|pool.?float/i;

export const escXml = s => String(s ?? '').replace(/[<>&"']/g, m =>
  ({ '<': '&lt;', '>': '&gt;', '&': '&amp;', '"': '&quot;', "'": '&apos;' }[m]));

/** Google kappt Titel bei 150 Zeichen — lieber am Wort trennen als mitten im Wort. */
export function kuerzeTitel(titel, max = 150) {
  const t = String(titel ?? '').trim();
  if (t.length <= max) return t;
  const schnitt = t.slice(0, max);
  const luecke = schnitt.lastIndexOf(' ');
  return (luecke > max * 0.6 ? schnitt.slice(0, luecke) : schnitt).trim();
}

/**
 * Gehört das Produkt in den Feed?
 * @returns {{ok: boolean, grund: string}} — `grund` ist immer gefüllt, auch bei ok:false,
 *   damit ein Lauf sagen kann, WARUM etwas fehlt (ein stummer Skip sieht aus wie „keine Daten").
 */
export function pruefeProdukt(p = {}) {
  const tags = p.tags || [];
  const treffer = sperrTags(tags);
  if (treffer.length) return { ok: false, grund: `Sperrtag: ${treffer.join(', ')}` };
  if (!p.bild) return { ok: false, grund: 'kein Titelbild' };
  if (!(+p.preis > 0)) return { ok: false, grund: 'kein Preis > 0' };
  if (!p.titel) return { ok: false, grund: 'kein Titel' };
  if (!(p.id || p.sku || p.handle)) return { ok: false, grund: 'keine ID (id/sku/handle fehlen)' };
  if (!p.link) return { ok: false, grund: 'kein Link' };
  if (RISIKO.test(p.titel) || RISIKO.test(p.marke || '')) return { ok: false, grund: 'Marken-/Safety-Risiko' };
  // AUCH DIE BESCHREIBUNG, gemessen am fertigen Live-Feed vom 24.10.: zwei generische
  // „Zauberer-Kostüm" trugen einen sauberen Titel, aber „Harry Potter lässt grüssen." im Text.
  // Google liest die Beschreibung mit — ein generisches Kostüm, das eine Lizenzfigur anruft, ist
  // genau der Fall „implied licensed product". Gefunden hat es nicht der Test, sondern die
  // Gegenprobe AM VEROEFFENTLICHTEN FEED; die Titelprüfung allein sah sie nie.
  // Betroffen sind 3 von 8084 Artikeln — der Preis dafür ist klein.
  const lizenz = (String(p.titel).match(LIZENZ) || [])[0]
    || (String(p.beschreibung ?? '').match(LIZENZ) || [])[0];
  if (lizenz) return { ok: false, grund: `Lizenzname: ${lizenz}` };
  return { ok: true, grund: 'im Feed' };
}

/**
 * Baut den `<item>`-Block. Erwartet ein flaches Produkt-Objekt (siehe merchant_feed.mjs).
 * Gibt `null` zurück, wenn `pruefeProdukt` ablehnt — der Aufrufer protokolliert den Grund.
 */
export function feedItem(p = {}, opt = {}) {
  if (!pruefeProdukt(p).ok) return null;
  const waehrung = p.waehrung || 'CHF';
  const z = [];
  const feld = (k, v) => { if (v !== undefined && v !== null && String(v) !== '') z.push(`<g:${k}>${escXml(v)}</g:${k}>`); };

  feld('id', p.id || p.sku || p.handle);
  feld('title', kuerzeTitel(p.titel));
  feld('description', String(p.beschreibung || p.titel).slice(0, 5000));
  feld('link', p.link);
  feld('image_link', p.bild);
  for (const w of (p.weitereBilder || []).slice(0, 10)) feld('additional_image_link', w);
  feld('availability', p.verfuegbar === false ? 'out of stock' : 'in stock');
  // Aktionspreis nur, wenn der Vergleichspreis WIRKLICH hoeher liegt — sonst meldet Google
  // „sale_price invalid". Dann ist der Listenpreis `price` und der Verkaufspreis `sale_price`.
  const aktion = +p.vergleichspreis > +p.preis;
  feld('price', `${(+(aktion ? p.vergleichspreis : p.preis)).toFixed(2)} ${waehrung}`);
  if (aktion) feld('sale_price', `${(+p.preis).toFixed(2)} ${waehrung}`);
  feld('condition', p.zustand || 'new');
  feld('brand', p.marke || 'LuxeStyle');

  // GTIN wenn vorhanden; sonst Marke + MPN; erst wenn beides fehlt, ehrlich identifier_exists=no.
  const gtin = String(p.gtin || '').replace(/\s/g, '');
  if (/^\d{8}$|^\d{12,14}$/.test(gtin)) feld('gtin', gtin);
  else if (p.sku) feld('mpn', p.sku);
  else feld('identifier_exists', 'no');

  feld('google_product_category', p.googleKategorie);
  feld('product_type', p.produktTyp);
  feld('item_group_id', p.gruppe);
  feld('age_group', p.altersgruppe);
  feld('gender', p.geschlecht);
  if (opt.versandLand && opt.versandPreis !== undefined) {
    z.push(`<g:shipping><g:country>${escXml(opt.versandLand)}</g:country>` +
      `<g:price>${escXml(`${(+opt.versandPreis).toFixed(2)} ${waehrung}`)}</g:price></g:shipping>`);
  }
  return `<item>\n${z.join('\n')}\n</item>`;
}

#!/usr/bin/env node
/* 🛒 merchant_feed.mjs — NUR LESEN: Google-Merchant-Produktfeed (kostenlose Shopping-Einträge)
 *
 * Baut aus den aktiven Produkten einen RSS-2.0-Feed nach Google-Merchant-Schema.
 * In Google Merchant Center als „geplanter Abruf" hinterlegbar.
 * Ausgabe: automation/autopilot/google-merchant-feed.xml
 *
 * WAS SICH AM 2026-10-17 GEÄNDERT HAT (gemessen, Bericht dropship/GOOGLE-MERCHANT-STAND-1710.md):
 *  - Der Feed schrieb bei JEDEM Artikel `identifier_exists: no` — dabei tragen **84 % der
 *    Fortura-Artikel einen Barcode (GTIN)**. Jetzt: echte GTIN, sonst Marke+MPN, erst dann `no`.
 *  - `google_product_category` fehlte komplett, obwohl **100 % der zuletzt geänderten 600
 *    Produkte** das Metafeld `mm-google-shopping.google_product_category` haben.
 *  - Gefiltert wurde nur über eine Titel-Liste; die Sperrtags des Katalogs
 *    (`nicht-google-bewerben`, `gmc-adult-pull`, `google-policy-flag` …) las niemand.
 *  - Versandangabe fehlte — Merchant Center meldete „Missing shipping info in some countries".
 *  - Bei Drosselung gab der Lauf still auf; jetzt `shopifyGql` mit wachsenden Pausen.
 *
 * REGEL: Dieser Lauf darf aussteigen, aber er muss den Grund nennen (Status + Antworttext).
 *
 * ENV: SHOPIFY_CLIENT_ID+SECRET (+SHOPIFY_SHOP) ODER SHOPIFY_ADMIN_TOKEN.
 *      FEED_QUERY (mehrere Abfragen mit `||` trennen) · SCAN (Deckel je Abfrage, Vorgabe 6000)
 *      SORT (ProductSortKeys, z. B. CREATED_AT) · REVERSE (0/1) · VERSAND_LAND/VERSAND_PREIS · OUT
 */
import fs from 'node:fs';
import path from 'node:path';
import { shopifyClientSecret } from '../lib/shopify_secret.mjs';
import { shopifyGql } from '../lib/shopify_gql.mjs';
import { feedItem, pruefeProdukt } from '../lib/gmc_feed_item.mjs';

const ROOT = path.resolve(new URL('../..', import.meta.url).pathname);
const OUT = process.env.OUT || path.join(ROOT, 'automation', 'autopilot', 'google-merchant-feed.xml');
const SHOP = process.env.SHOPIFY_SHOP || 'au3j0y-hq.myshopify.com';
const API = '2025-01';
const STORE = 'https://luxestyle.ch';
const SCAN = +(process.env.SCAN || 6000);
const VERSAND = { versandLand: process.env.VERSAND_LAND || 'CH', versandPreis: +(process.env.VERSAND_PREIS ?? 7) };
// Vorgabe bewusst NICHT „nur was schon auf dem Google-Kanal liegt": der Feed ist genau der Weg
// für die Artikel, die dort fehlen. Gemessen 17.10.: 1890 aktive Produkte sind nicht auf
// „Google & YouTube", 1689 davon ohne jeden Sperrtag, und 1604 von diesen sind Fortura-Ware aus
// dem Schweizer Lager mit echtem Barcode (97 % GTIN) — das beste Shopping-Material des Shops.
// Die Sperrtags und der Marken-/Safety-Filter in `gmc_feed_item.mjs` halten den Rest draussen.
// MEHRERE ABFRAGEN, weil EIN Fenster nicht reicht (gemessen 24.10.): ohne Sortierung beginnt
// jeder Lauf am selben Katalogende und erreicht die Fortura-Ware nie — genau die mit den
// Barcodes. Darum `FEED_QUERY` mit `||` trennbar; jede Abfrage bekommt ihr eigenes SCAN-Fenster,
// Dubletten fallen ueber `ids` weg. Dieselbe Fensterfalle wie beim SEO-Titel-Lauf.
const QUERIES = (process.env.FEED_QUERY || 'status:active||status:active AND tag:fortura')
  .split('||').map(q => q.trim()).filter(Boolean);
// Ohne SORT entscheidet Shopify (Vorgabe) — das ist der alte Lauf, unveraendert.
const SORT = (process.env.SORT || '').trim() || null;
const REVERSE = process.env.REVERSE === undefined ? null : process.env.REVERSE !== '0';

async function holeToken() {
  if (process.env.SHOPIFY_ADMIN_TOKEN) return process.env.SHOPIFY_ADMIN_TOKEN;
  const id = process.env.SHOPIFY_CLIENT_ID;
  const sec = shopifyClientSecret(process.env.SHOPIFY_CLIENT_SECRET);
  if (!id || !sec) { console.log('ABBRUCH: SHOPIFY_CLIENT_ID oder _SECRET fehlt (kein Token holbar).'); return null; }
  const r = await fetch(`https://${SHOP}/admin/oauth/access_token`, {
    method: 'POST', headers: { 'Content-Type': 'application/json' },
    body: JSON.stringify({ client_id: id, client_secret: sec, grant_type: 'client_credentials' }) });
  const txt = await r.text();
  let j = {}; try { j = JSON.parse(txt); } catch {}
  if (!j.access_token) {
    console.log(`ABBRUCH: Token-Anfrage HTTP ${r.status} · Antwort ${txt.slice(0, 200)} · Secret-Länge ${sec.length}`);
    return null;
  }
  return j.access_token;
}

const TOKEN = await holeToken();
if (!TOKEN) process.exit(1);

const SEITE = `query($q:String!,$after:String,$sort:ProductSortKeys,$rev:Boolean){
  products(first:50, query:$q, after:$after, sortKey:$sort, reverse:$rev){
  pageInfo{ hasNextPage endCursor }
  edges{ node{
    title handle onlineStoreUrl vendor productType tags
    beschreibung: description(truncateAt:900)
    featuredImage{ url }
    media(first:4){ edges{ node{ preview{ image{ url } } } } }
    mf: metafields(first:12, namespace:"mm-google-shopping"){ edges{ node{ key value } } }
    variants(first:1){ edges{ node{ sku barcode price compareAtPrice availableForSale } } }
  } }
} }`;

let gesehen = 0;
const items = [];
const ids = new Set();
const gruende = new Map();
const jeAbfrage = [];
for (const QUERY of QUERIES) {
 let cursor = null, nQ = 0, vorher = items.length;
 while (nQ < SCAN) {
  const daten = await shopifyGql(SHOP, API, TOKEN, SEITE,
    { q: QUERY, after: cursor, sort: SORT, rev: REVERSE });
  const p = daten?.products;
  if (!p) { console.log(`ABBRUCH: keine Produktdaten · ${JSON.stringify(daten).slice(0, 200)}`); process.exit(1); }
  for (const e of p.edges) {
    const x = e.node; gesehen++; nQ++;
    const mf = Object.fromEntries(x.mf.edges.map(m => [m.node.key, m.node.value]));
    const v = x.variants.edges[0]?.node || {};
    const bilder = x.media.edges.map(m => m.node.preview?.image?.url).filter(Boolean);
    const produkt = {
      // ID = handle, NICHT die SKU: gemessen 17.10. teilten sich 450 von 3932 Artikeln eine SKU
      // (CJ vergibt dieselbe Varianten-SKU mehrfach). Google weist einen Feed mit doppelten IDs
      // ab — der alte Generator schrieb `sku || handle` und hätte genau das geliefert.
      id: x.handle, sku: v.sku, handle: x.handle, gtin: v.barcode,
      titel: x.title, beschreibung: x.beschreibung || x.title,
      link: x.onlineStoreUrl || `${STORE}/products/${x.handle}`,
      bild: x.featuredImage?.url, weitereBilder: bilder.filter(u => u !== x.featuredImage?.url),
      preis: v.price, vergleichspreis: v.compareAtPrice, waehrung: 'CHF',
      verfuegbar: v.availableForSale !== false,
      marke: x.vendor || 'LuxeStyle', produktTyp: x.productType, tags: x.tags,
      googleKategorie: mf.google_product_category, altersgruppe: mf.age_group,
      geschlecht: mf.gender, zustand: mf.condition || 'new', gruppe: x.handle,
    };
    const urteil = pruefeProdukt(produkt);
    if (!urteil.ok) {
      const schlagwort = urteil.grund.startsWith('Sperrtag') ? 'Sperrtag' : urteil.grund;
      gruende.set(schlagwort, (gruende.get(schlagwort) || 0) + 1);
      continue;
    }
    if (ids.has(produkt.id)) { gruende.set('doppelte ID', (gruende.get('doppelte ID') || 0) + 1); continue; }
    ids.add(produkt.id);
    items.push(feedItem(produkt, VERSAND));
  }
  if (!p.pageInfo.hasNextPage) break;
  cursor = p.pageInfo.endCursor;
 }
 jeAbfrage.push({ query: QUERY, gelesen: nQ, neu: items.length - vorher, gedeckelt: nQ >= SCAN });
}

const xml = `<?xml version="1.0" encoding="UTF-8"?>
<rss version="2.0" xmlns:g="http://base.google.com/ns/1.0">
<channel>
<title>LuxeStyle CH — Produktfeed</title>
<link>${STORE}</link>
<description>LuxeStyle Schweizer Mode-Shop — Google-Merchant-Feed</description>
${items.join('\n')}
</channel>
</rss>`;
fs.mkdirSync(path.dirname(OUT), { recursive: true });
fs.writeFileSync(OUT, xml);
const mitGtin = items.filter(i => i.includes('<g:gtin>')).length;
const mitKat = items.filter(i => i.includes('<g:google_product_category>')).length;
console.log(`✅ ${path.relative(ROOT, OUT)}: ${items.length} Artikel von ${gesehen} geprüften.`);
console.log(`   davon mit GTIN ${mitGtin} · mit google_product_category ${mitKat}`);
// Die gelaufene Region MIT nennen: eine Zahl ohne sie laedt zum Fehlschluss ein,
// der Lauf habe den ganzen Katalog gesehen.
console.log(`   Sortierung: ${SORT || 'Shopify-Vorgabe'}${REVERSE === null ? '' : REVERSE ? ' (rueckwaerts)' : ' (vorwaerts)'}`);
for (const a of jeAbfrage) console.log(`   Abfrage «${a.query}»: ${a.gelesen} gelesen` +
  `${a.gedeckelt ? ` (Teilmessung, Deckel ${SCAN})` : ''} · ${a.neu} neu im Feed`);
for (const [grund, n] of [...gruende].sort((a, b) => b[1] - a[1])) console.log(`   ausgelassen · ${grund}: ${n}`);
